function readInput(){const active=state.driving&&!state.paused;input.throttle=active&&(keys.has('KeyW')||keys.has('ArrowUp')||touch.has('throttle'));input.brake=active&&(keys.has('KeyS')||keys.has('ArrowDown')||touch.has('brake'));input.steer=active?Number(keys.has('KeyD')||keys.has('ArrowRight')||touch.has('right'))-Number(keys.has('KeyA')||keys.has('ArrowLeft')||touch.has('left')):0;input.handbrake=active&&(keys.has('Space')||touch.has('handbrake'));input.boost=active&&(keys.has('ShiftLeft')||keys.has('ShiftRight')||touch.has('boost'));}
